def pool_status(entries: list) -> dict:
    total = 0
    valid_count = 0
    for e in entries:
        # 忽略 None，但非 None 的不可迭代对象也视为一个有效条目，长度计为 0
        if e is None:
            continue
        if hasattr(e, '__len__'):
            total += len(e)
        else:
            total += 0
        valid_count += 1
    return {"total": total, "count": valid_count}

