def lookup_metric(metrics: dict, layer_name: str, key: str):
    # 校验输入类型与键存在性，任何不满足条件均返回 None
    if not isinstance(metrics, dict):
        return None
    if layer_name not in metrics:
        return None
    layers = metrics[layer_name]
    if not isinstance(layers, dict):
        return None
    if key not in layers:
        return None
    return layers[key]

def summarize(metrics: dict, layer_name: str):
    total = 0
    if not isinstance(metrics, dict):
        return total
    layer = metrics.get(layer_name)
    if not isinstance(layer, dict):
        return total
    for key in layer:
        value = lookup_metric(metrics, layer_name, key)
        if isinstance(value, (int, float)):
            total += value
    return total

def rank(metrics: dict, layer_name: str, k: int):
    if not isinstance(metrics, dict):
        return []
    layer = metrics.get(layer_name)
    if not isinstance(layer, dict):
        return []
    if k is None:
        k = 0
    if not isinstance(k, int):
        try:
            k = int(k)
        except (ValueError, TypeError):
            k = 0
    if k <= 0:
        return []
    # 仅对有效 key 进行排序，无效 key（lookup_metric 返回 None）跳过
    valid_items = []
    for s in layer:
        v = lookup_metric(metrics, layer_name, s)
        if v is not None:
            valid_items.append((s, v))
    valid_items.sort(key=lambda t: -t[1])
    keys = [s for s, _ in valid_items]
    return keys[:k]
